def parse(t):
 def rec(n):
  if isinstance(n,ast.Constant):return q.atom(n.value)
  if isinstance(n,ast.Name):return q.atom(1,names[n.id])
  if isinstance(n,ast.UnaryOp):return q.scale(rec(n.operand),-1 if isinstance(n.op,ast.USub)else 1)
  if isinstance(n,ast.BinOp):
   a=rec(n.left)
   if isinstance(n.op,ast.Pow):
    n0=ast.literal_eval(n.right)
    if n0<0:
     assert len(a)==1
     e,c=next(iter(a.items()));return {tuple(n0*v for v in e):c**n0}
    z=q.atom(1)
    for _ in range(n0):z=q.mul(z,a)
    return z
   b=rec(n.right)
   if isinstance(n.op,ast.Add):return q.add(a,b)
   if isinstance(n.op,ast.Sub):return q.add(a,q.scale(b,-1))
   if isinstance(n.op,ast.Mult):return q.mul(a,b)
   if isinstance(n.op,ast.Div):
    assert len(b)==1
    e,c=next(iter(b.items()));return q.mul(a,{tuple(-v for v in e):1/c})
  raise ValueError(ast.dump(n))
